export function collectionImageSource(path) {
  const index = aliases[path?.replace(/^\.\//, '')];
  if (index === undefined) return null;
  const [stem, width, height, dimensions] = records[index];
  const variants = dimensions.map(([width,height]) => ({src: `${stem}-${width}.webp`,width,height}));
  const [previewWidth, previewHeight, previewSrc] = inlinePreviews[index];
  const preview = {src:previewSrc,width:previewWidth,height:previewHeight};
  const mobile = variants.find(image => image.width >= 960) || variants.at(-1);
  const full = variants.at(-1);
  return {src:full.src,width,height,variants,mobileSrc:mobile.src,mobileWidth:mobile.width,mobileHeight:mobile.height,
    previewSrc:preview.src,previewWidth:preview.width,previewHeight:preview.height,
    srcset:variants.filter(image => image.width >= Math.min(480,width)).map(image => `${image.src} ${image.width}w`).join(', ')};
}
export function optimizeCollectionPhotograph(photo) {
  return {...photo,...collectionImageSource(photo.src)};
}
